    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours or not sixes:
        return out
    for r, c in sixes:
        out[r][c] = 0

    r0, r1 = min(r for r, c in fours), max(r for r, c in fours)
    c0, c1 = min(c for r, c in fours), max(c for r, c in fours)
    mr0, mr1 = min(r for r, c in sixes), max(r for r, c in sixes)
    mc0, mc1 = min(c for r, c in sixes), max(c for r, c in sixes)
    row_counts = [sum(grid[r][c] == 6 for c in range(w)) for r in range(mr0, mr1 + 1)]
    widest = row_counts.index(max(row_counts))

    if widest == 0 or widest == len(row_counts) - 1:
        # T marker indicates a horizontal reflection, toward the marker's side.
        marker_center2 = mc0 + mc1
        object_center2 = c0 + c1
        if marker_center2 < object_center2:
            for r, c in fours:
                cc = 2 * c0 - 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
        else:
            for r, c in fours:
                cc = 2 * c1 + 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
    else:
        # Cross marker: stem offset from bar center selects vertical direction.
        bar_row = mr0 + widest
        bar_cols = [c for r, c in sixes if r == bar_row]
        stem_cols = [c for r, c in sixes if r != bar_row]
        bar_center2 = min(bar_cols) + max(bar_cols)
        stem_center2 = 2 * sum(stem_cols) // len(stem_cols) if stem_cols else bar_center2
        if stem_center2 > bar_center2:
            for r, c in fours:
                rr = 2 * r1 + 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
        else:
